from pathlib import Path
p=Path('client/main.ts')
s=p.read_text(encoding='utf-8')
s=s.replace('import "./style.css";\nimport "./refresh.css";\nimport "./coastal.css";\nimport "./reference-ui.css";', 'import "./brand.css";\nimport { brandLogo, button, dialog, focusDialog, releaseDialog } from "./ui.ts";')
def replace_func(name, nextname, body):
    global s
    a=s.index('function '+name+'(')
    b=s.index('function '+nextname+'(',a)
    s=s[:a]+body+'\n'+s[b:]

